import {openStore,STORE_LIMITS} from './storage.js';
import {LEVELS,REGIONS,assess,solution,indexContent,availableMissions,nextMission,nextActivity,newEvent,placementRecommendation,suggestPractice} from './learning.js';
import {emblem,islandArt} from './world.js';
import {applyQuality} from './quality.js';
import {createCloud} from './cloud.js';
import {registerOffline} from './offline.js';
import {createExpedition,replayExpedition,findRoute} from './expedition.js';
import {explorationView,parseWorldPlan} from './exploration-view.js';
import {journeyProgress} from './journey.js';
import {studioView} from './studio-view.js';

const app=document.querySelector('#app');
// Keep the native file chooser outside rebuilt views. Replacing/detaching it
// between the browser's input/change events can otherwise drop an import.
const importInput=document.createElement('input');
Object.assign(importInput,{type:'file',id:'import-file',accept:'application/json,.json',hidden:true});
app.after(importInput);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store,pack,boards=[],profiles=[],profile=null,events=[],progress,cloud,qualityCleanup=()=>{},refreshGeneration=0,draftTimer=null,draftSave=Promise.resolve(),renderedContext=null;
const ui={screen:'atlas',mission:null,activity:null,answer:null,feedback:null,supported:false,stage:'intro',busy:false,error:'',notice:'',showModel:false,review:false,placement:[],placementItems:[],placementIndex:0,cloudStatus:{state:'disabled',configured:false},draftKey:'',lastSaved:null};
const t=(en,vi)=>profile?.settings.language==='vi'?vi:en;
const loc=v=>v?.[profile?.settings.language??'en']??v?.en??'';
const btn=(label,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const selected=(a,b)=>a===b?' selected':'';
const pressed=(a,b)=>`aria-pressed="${a===b}"`;
const content=()=>indexContent(pack);
function currentActivity(){return content().activities.get(ui.activity);}
function currentMission(){return content().missions.get(ui.mission);}
function setActive(id){try{localStorage.setItem('atlas-active-profile',id??'');}catch{/* IDB is authoritative; this shortcut is optional. */}}
function errorMessage(error){return error?.message??String(error);}

async function refresh(){
 const generation=++refreshGeneration,id=profile?.id??null;
 const nextProfiles=await store.listProfiles();
 const nextProfile=id?await store.getProfile(id):null;
 const nextEvents=nextProfile?await store.getEvents(id):[];
 if(generation!==refreshGeneration||(profile?.id??null)!==id||(nextProfile&&profile&&nextProfile.revision<profile.revision))return;
 const preferencesChanged=JSON.stringify(profile?.settings)!==JSON.stringify(nextProfile?.settings);
 profiles=nextProfiles;profile=nextProfile;events=nextEvents;progress=journeyProgress(events,pack,boards);if(id&&!profile)ui.screen='profiles';if(preferencesChanged)setPreferences();
}
async function selectProfile(id){globalThis.speechSynthesis?.cancel();++refreshGeneration;profile=await store.getProfile(id);if(!profile)throw new Error('Profile not found');setActive(id);ui.screen=profile.journey.onboarded?'atlas':'onboard';ui.mission=null;ui.activity=null;await refresh();setPreferences();}
function setPreferences(){qualityCleanup();document.documentElement.lang=profile?.settings.language==='vi'?'vi':'en';const skip=document.querySelector('.skip-link');if(skip)skip.textContent=t('Skip to content','Đến nội dung chính');if(profile)qualityCleanup=applyQuality(profile.settings);}
async function append(kind,payload){await store.appendEvent(profile.id,newEvent(kind,payload));ui.lastSaved=new Date();await refresh();}
async function saveDraft(){
 if(ui.screen!=='mission'||ui.stage!=='activity'||!ui.activity||ui.feedback||ui.submitting||!profile)return;
 const a=currentActivity();if(!a)return;
 const value=JSON.stringify({answer:ui.answer,supported:ui.supported});if(value===ui.draftKey||(ui.answer===null&&!ui.supported))return;
 const profileId=profile.id,activityId=a.id,event=newEvent('draft',{activityId,missionId:ui.mission,answer:ui.answer,supported:ui.supported});
 const operation=draftSave.catch(()=>{}).then(()=>store.appendEvent(profileId,event));draftSave=operation;await operation;
 if(profile?.id===profileId&&ui.activity===activityId){ui.draftKey=value;ui.lastSaved=new Date();await refresh();}
}
function draftStatus(){const el=app.querySelector('.draft-status');if(!el||ui.screen!=='mission'||ui.stage!=='activity')return;const saved=ui.feedback||JSON.stringify({answer:ui.answer,supported:ui.supported})===ui.draftKey;const message=saved?t('Saved on this device','Đã lưu trên thiết bị'):t('Draft not yet saved…','Bản nháp chưa lưu…');if(el.textContent!==message)el.textContent=message;}
function queueDraft(){clearTimeout(draftTimer);draftStatus();draftTimer=setTimeout(()=>{if(!ui.busy&&!ui.submitting)saveDraft().then(draftStatus).catch(reportError);},1500);}
async function navigate(screen){await saveDraft();globalThis.speechSynthesis?.cancel();ui.screen=screen;ui.error='';ui.feedback=null;ui.showModel=false;render(true);}
function initActivity(a){
 globalThis.speechSynthesis?.cancel();
 ui.activity=a.id;ui.feedback=null;ui.showModel=false;ui.supported=false;
 const draft=ui.review?null:progress.drafts[a.id];
 ui.answer=draft?.answer??(a.type==='order'?shuffle(a.tokens.map(x=>x.id),a.id):a.type==='match'?{}:a.type==='writing'?{text:'',checks:[]}:null);
 // Resuming a stored response is useful practice, but is not fresh retrieval.
 ui.supported=Boolean(draft);ui.draftKey=JSON.stringify({answer:ui.answer,supported:ui.supported});
}
// Stable non-answer ordering: different across activities, safe across re-renders.
function shuffle(values,seed){
 const out=[...values];let n=[...seed].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,19);
 for(let i=out.length-1;i>0;i--){n=(n*1664525+1013904223)>>>0;const j=n%(i+1);[out[i],out[j]]=[out[j],out[i]];}
 if(out.length>1&&out.every((v,i)=>v===values[i]))out.push(out.shift());return out;
}
async function beginMission(id,reviewActivity=null){
 await saveDraft();const mission=content().missions.get(id);if(!mission)throw new Error('Expedition unavailable');
 const item=availableMissions(pack,mission.level,progress).find(m=>m.mission.id===id);if(!reviewActivity&&!item.unlocked)throw new Error(t('Complete the preceding expedition first.','Hãy hoàn thành chuyến khám phá trước.'));
 ui.screen='mission';ui.mission=id;ui.review=Boolean(reviewActivity);ui.stage=reviewActivity?'activity':profile.settings.mode==='kids'?'intro':profile.settings.mode==='balanced'?'world':progress.completedMissions.has(id)?'world':'activity';ui.worldQueue=[];ui.worldPlan='';ui.worldTranslation=false;ui.worldHint=false;ui.worldRoute=null;ui.worldInspected=null;initActivity(reviewActivity??nextActivity(mission,progress));render(true);
}

function currentBoard(){return boards.find(b=>b.missionId===ui.mission);}
function worldView(){const board=currentBoard();if(!board)return `<section class="panel"><h1>${t('This route is being charted.','Lộ trình đang được hoàn thiện.')}</h1>${btn(t('Read a field clue','Đọc manh mối'),'activity',`data-id="${currentMission().activities[0].id}"`,'primary')}</section>`;const saved=progress.worlds.states[board.id];return explorationView({board,state:saved?.state??createExpedition(board),commands:saved?.commands??[],mode:profile.settings.mode,language:profile.settings.language,mission:currentMission(),progress,queue:ui.worldQueue??[],planText:ui.worldPlan??'',translation:ui.worldTranslation,hint:ui.worldHint,route:ui.worldRoute,inspected:ui.worldInspected});}
async function saveWorld(commands){const board=currentBoard();replayExpedition(board,commands);await append('expedition',{boardId:board.id,commands,supported:Boolean(progress.worlds.states[board.id]?.supported||ui.worldTranslation||ui.worldHint||ui.worldRoute)});render();}
async function runWorld(added){const board=currentBoard(),prior=progress.worlds.states[board.id]?.commands??[],commands=[...prior,...added];if(commands.length>400)throw new Error(t('This route is getting long. Reset the route to explore again; earned discoveries are kept.','Lộ trình đã dài. Làm lại để khám phá tiếp; khám phá đã nhận vẫn được giữ.'));await saveWorld(commands);}

function header(){
 const mode=profile?.settings.mode??'balanced';
 return `<header class="masthead"><a class="wordmark" href="#" data-action="atlas"><img src="./assets/atlas-mark.svg" alt="" width="34" height="34"><span>The Unfolding <strong>Atlas</strong></span></a><span class="edition">${t('A world worth understanding','Một thế giới đáng khám phá')}</span>${profile?`<button type="button" class="profile-pill" data-action="profiles"><span class="avatar">${esc(profile.name.slice(0,1))}</span>${esc(profile.name)}<span aria-hidden="true">⌄</span></button>`:''}</header>
 ${profile&&ui.screen!=='onboard'?`<nav class="main-nav" aria-label="${t('Main navigation','Điều hướng chính')}">${[['atlas',t('Explore','Khám phá')],['journal',t('Field journal','Nhật ký')],['review',t('Practice','Ôn tập')],['settings',t('Settings','Cài đặt')]].map(([route,label])=>`<button type="button" data-action="${route}" ${ui.screen===route?'aria-current="page"':''}>${label}${route==='review'&&progress.due.length?` <span class="badge">${progress.due.length}</span>`:''}</button>`).join('')}<span class="nav-mode">${{kids:t('Play first','Chơi để học'),balanced:t('Learn & play','Học và chơi'),serious:t('Study first','Học tập trung')}[mode]}</span></nav>`:''}`;
}

function footer(){return `<footer class="site-footer"><span>✦ The Unfolding Atlas</span><span>${t('Curiosity travels well. Take a break whenever you like.','Trí tò mò luôn đồng hành. Bạn có thể nghỉ bất cứ lúc nào.')}</span><span class="save-status" role="status">${profile?t('Local profile · backup in Settings','Hồ sơ thiết bị · sao lưu trong Cài đặt'):t('Private family edition','Phiên bản gia đình')}</span></footer>`;}

function profilesScreen(){
 return `<section class="welcome"><div><p class="eyebrow">THE UNFOLDING ATLAS</p><h1>${t('Every great journey starts with curiosity.','Mỗi hành trình bắt đầu từ trí tò mò.')}</h1><p class="lede">${t('Make a little light. Grow something unexpected. Discover what English can help you do.','Thắp một chút sáng. Nuôi điều bất ngờ. Khám phá những gì tiếng Anh giúp bạn thực hiện.')}</p><p>${t('Choose your traveler. Progress stays on this device; optional family sign-in adds cross-device backup.','Chọn người khám phá. Tiến độ được lưu trên thiết bị; đăng nhập gia đình tùy chọn giúp đồng bộ.')}</p></div>${islandArt('A1',0)}</section>
 <section class="panel profile-section"><div class="section-heading"><div><p class="eyebrow">${t('YOUR TRAVELERS','NGƯỜI KHÁM PHÁ')}</p><h2>${t('Who’s unfolding the map?','Ai đang mở bản đồ?')}</h2></div></div><div class="profile-grid">${profiles.map(p=>btn(`<span class="avatar">${esc(p.name.slice(0,1))}</span><strong>${esc(p.name)}</strong><small>${p.kind==='dependent'?t('Family dependent','Thành viên phụ thuộc'):t('Personal profile','Hồ sơ cá nhân')}</small>`,'choose-profile',`data-id="${p.id}"`,'traveler')).join('')}</div>
 <details ${profiles.length?'':'open'}><summary>${t('Create a traveler','Tạo người khám phá')}</summary><form data-form="create-profile" class="form-row"><label>${t('Display name (no full name needed)','Tên hiển thị (không cần họ tên thật)')}<input name="name" maxlength="40" required autocomplete="off" placeholder="${t('e.g. River','Ví dụ: Mây')}"></label><label>${t('Profile type','Loại hồ sơ')}<select name="kind"><option value="independent">${t('Personal','Cá nhân')}</option><option value="dependent">${t('Guardian managed','Người giám hộ quản lý')}</option></select></label><label>${t('Guardian, for dependent profile','Người giám hộ của hồ sơ phụ thuộc')}<select name="guardianId"><option value="">${t('Choose if needed','Chọn nếu cần')}</option>${profiles.filter(p=>p.kind==='independent').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><button class="primary" type="submit">${t('Open my atlas','Mở bản đồ')}</button></form></details>
 <p class="fineprint">${t('Local profiles are not password protected. Anyone using this browser can switch between them. Guardian settings are convenience controls. Use separate browser/device accounts for privacy.','Hồ sơ trên thiết bị không có mật khẩu. Người dùng trình duyệt này có thể đổi hồ sơ. Chức năng giám hộ hỗ trợ quản lý, không phải khóa bảo mật. Dùng tài khoản thiết bị/trình duyệt riêng để bảo vệ riêng tư.')}</p>
 <div class="button-row">${btn(t('Restore a backup','Khôi phục bản sao'),'import')}${btn(t('Family cloud connection','Kết nối đám mây gia đình'),'cloud-panel')}</div>${cloudPanel()}</section>`;
}

function modeCards(){return `<div class="mode-cards">${[
 ['kids','✦',t('Play first','Chơi để học'),t('Explore with Nim, reveal clues, build a discovery one piece at a time.','Cùng Nim tìm manh mối và tạo khám phá từng mảnh một.')],
 ['balanced','◈',t('Learn & play','Học và chơi'),t('Choose an expedition, solve a world problem, keep a field journal.','Chọn chuyến khám phá, giải thử thách và ghi nhật ký.')],
 ['serious','⌘',t('Study first','Học tập trung'),t('A direct workspace with objectives, clear feedback and evidence.','Không gian tập trung với mục tiêu, phản hồi và bằng chứng học tập.')],
 ].map(([id,icon,label,description])=>`<button type="button" class="mode-card ${profile.settings.mode===id?'chosen':''}" data-action="mode" data-value="${id}" ${pressed(profile.settings.mode,id)}><span class="mode-icon">${icon}</span><strong>${label}</strong><span>${description}</span></button>`).join('')}</div>`;}
function onboardScreen(){return `<section class="onboard panel"><p class="eyebrow">${t('YOUR ATLAS, YOUR WAY','BẢN ĐỒ THEO CÁCH CỦA BẠN')}</p><h1>${t('What kind of journey today?','Hôm nay bạn muốn khám phá thế nào?')}</h1><p class="lede">${t('Choose how you like to learn. Every style shares the same progress. You can change it anytime.','Chọn cách học bạn yêu thích. Mọi chế độ dùng chung tiến độ. Bạn có thể đổi bất cứ lúc nào.')}</p>${modeCards()}<div class="settings-grid"><label>${t('Guidance language','Ngôn ngữ hướng dẫn')}<select data-setting="language"><option value="en"${selected(profile.settings.language,'en')}>English only</option><option value="vi"${selected(profile.settings.language,'vi')}>Tiếng Việt hỗ trợ</option></select></label><label>${t('Starting practice range','Mức luyện tập ban đầu')}<select data-journey="region">${LEVELS.map(l=>`<option${selected(profile.journey.region,l)}>${l}</option>`).join('')}</select></label></div><p>${t('Unsure where to begin? A short orientation can suggest a range. It does not certify a CEFR level. You can explore any band.','Chưa biết bắt đầu đâu? Bài định hướng ngắn gợi ý mức luyện tập, không chứng nhận CEFR. Bạn có thể khám phá mọi mức.')}</p><div class="button-row">${btn(t('Start exploring →','Bắt đầu khám phá →'),'finish-onboard','','primary')}${btn(t('Try the orientation','Thử bài định hướng'),'start-placement')}</div></section>`;}

function atlasScreen(){
 const level=profile.journey.region,r=REGIONS.find(r=>r.level===level),missions=availableMissions(pack,level,progress),done=missions.filter(m=>m.complete).length,next=nextMission(pack,level,profile.settings.mode==='serious'?{...progress,rewards:progress.completedMissions}:progress);
 return `${practiceBanner()}<section class="hero"><div class="hero-copy"><p class="eyebrow">${t('CHAPTER','CHƯƠNG')} ${LEVELS.indexOf(level)+1} / 6 · ${level}</p><h1>${esc(loc(r.name))}</h1><p class="lede">${esc(loc(r.description))}</p><p>${profile.settings.mode==='kids'?t('Nim found a folded map. Each discovery brings a little more of this world to life. Ready to help?','Nim tìm thấy tấm bản đồ gấp. Mỗi khám phá làm thế giới thêm sống động. Bạn giúp Nim nhé?'):profile.settings.mode==='serious'?t('Read, retrieve, construct and reflect. World completion and independent language evidence are tracked separately.','Đọc, nhớ lại, xây dựng và suy ngẫm. Hoàn thành thế giới và bằng chứng ngôn ngữ độc lập được ghi riêng.'):t('The map is unfinished. Follow a clue, make a plan, and leave this place a little brighter than you found it.','Bản đồ còn dang dở. Theo manh mối, lập kế hoạch và làm nơi này sáng hơn lúc bạn đến.')}</p><div class="button-row">${next?btn(t('Continue the journey →','Tiếp tục hành trình →'),'begin',`data-id="${next.id}"`,'primary'):btn(t('Visit your discoveries →','Xem các khám phá →'),'journal','','primary')}${progress.due.length?btn(`${t('Review ready','Đến lúc ôn')} · ${progress.due.length}`,'review'):''}</div><div class="hero-meta"><span>◇ ${done}/${missions.length} ${t('discoveries','khám phá')}</span><span>◎ ${level} ${t('practice range','mức luyện tập')}</span></div></div><div class="hero-world">${islandArt(level,done)}<span class="world-caption">${t('A little more unfolds with every discovery.','Mỗi khám phá mở thêm một phần thế giới.')}</span></div></section>
 <section aria-label="${t('Regions','Các vùng')}"><div class="region-strip">${REGIONS.map(region=>{const n=pack.missions.filter(m=>m.level===region.level&&progress.rewards.has(m.id)).length;return `<button type="button" class="region-tab ${level===region.level?'active':''}" data-action="region" data-value="${region.level}" ${pressed(level,region.level)}>${emblem(region.icon)}<span><strong>${region.level}</strong><small>${esc(loc(region.name))}</small></span>${n?`<span class="region-count">${n}</span>`:''}</button>`;}).join('')}</div></section>
 <section class="expeditions"><div class="section-heading"><div><p class="eyebrow">${t('FOLLOW YOUR CURIOSITY','THEO TRÍ TÒ MÒ')}</p><h2>${profile.settings.mode==='serious'?t('Learning path','Lộ trình học'):t('An unfinished corner of the world','Một góc thế giới còn dang dở')}</h2></div><span class="fineprint">${t('Explore any band. Unlock each region’s path through play.','Khám phá mọi mức. Mở lộ trình mỗi vùng bằng cách chơi.')}</span></div><div class="mission-grid">${missions.map(({mission:m,unlocked,complete},i)=>`<article class="mission-card ${!unlocked?'locked':''}"><div class="card-top"><span class="chapter-number">0${i+1}</span>${emblem(r.icon)}<span class="chip">${complete?t('Discovered','Đã khám phá'):progress.completedMissions.has(m.id)?t('Field clues complete','Đã xong manh mối'):unlocked?t('Ready to explore','Sẵn sàng'):t('Along the path','Trên lộ trình')}</span></div><h3>${esc(loc(m.title))}</h3><p>${esc(loc(m.summary))}</p><p class="card-objective">${esc(loc(m.objective))}</p><div class="card-bottom"><span>5 ${t('moments','chặng')} · ${m.level}</span>${btn(complete?t('Revisit ↗','Trở lại ↗'):unlocked?t('Explore →','Khám phá →'):t('Complete earlier path','Hoàn thành chặng trước'),'begin',`data-id="${m.id}" ${unlocked?'':'disabled'}`,unlocked?'text-button':'')}</div></article>`).join('')}</div></section>
 <aside class="observatory-invitation"><div>${emblem('star')}<h3>${t('A little light at the old observatory','Một chút ánh sáng ở đài quan sát cũ')}</h3><p>${t('Give Nim a plan. Move a mirror. See what changes when the mist rolls in. A free construction sandbox, separate from assessed learning.','Lập kế hoạch cho Nim. Xoay gương. Xem điều gì đổi khi sương đến. Không gian thử nghiệm tự do, tách biệt đánh giá học tập.')}</p></div><a class="button" href="./observatory.html">${t('Visit the observatory ↗','Đến đài quan sát ↗')}</a></aside>`;
}

function practiceBanner(){
 if(progress.rewards.size===pack.missions.length)return `<aside class="atlas-finale"><div class="finale-emblems">${REGIONS.map(r=>emblem(r.icon)).join('')}</div><p class="eyebrow">${t('A WORLD UNFOLDED BY YOU','THẾ GIỚI DO BẠN MỞ RA')}</p><h2>${t('The last fold opens onto a new beginning.','Nếp gấp cuối mở ra một khởi đầu mới.')}</h2><p>${t('Nim sets down the finished map. There is a place for every discovery—and room in the margins for everything you will learn next. Your journeys remain here to revisit.','Nim đặt tấm bản đồ hoàn chỉnh xuống. Mỗi khám phá có một chỗ, và lề giấy vẫn dành cho điều bạn sẽ học tiếp. Mọi hành trình ở đây để bạn trở lại.')}</p>${btn(t('Open my field journal →','Mở nhật ký của mình →'),'journal','','primary')}</aside>`;
 const suggestion=suggestPractice(progress,profile.journey.region);
 if(suggestion.action==='review')return `<aside class="practice-suggestion"><p>${t('A couple of recent clues deserve another look. A short review may help.','Một vài manh mối gần đây đáng xem lại. Ôn ngắn có thể giúp bạn.')}</p>${btn(t('Try targeted practice →','Luyện tập trọng tâm →'),'review','','text-button')}</aside>`;
 if(suggestion.action==='region')return `<aside class="practice-suggestion"><p>${t('Your recent independent responses suggest trying a stretch expedition. This is a practice suggestion, not a level award.','Các câu trả lời độc lập gần đây gợi ý thử chuyến khám phá khó hơn. Đây là gợi ý luyện tập, không phải chứng nhận lên trình độ.')}</p>${btn(`${t('Explore','Khám phá')} ${suggestion.level} →`,'region',`data-value="${suggestion.level}"`,'text-button')}</aside>`;
 return '';
}

function activityControls(a,placement=false){
 const disabled=Boolean(ui.feedback);const attr=disabled?'disabled':'';
 if(a.type==='choice')return `<div class="choice-grid">${shuffle(a.options,a.id).map((o,i)=>`<button type="button" class="choice ${ui.answer===o.id?'chosen':''}" data-action="choose" data-value="${o.id}" ${pressed(ui.answer,o.id)} ${attr}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span lang="en">${esc(o.text)}</span>${profile.settings.mode==='kids'?'<span class="choice-arrow" aria-hidden="true">✦</span>':''}</button>`).join('')}</div>`;
 if(a.type==='gap')return `<label class="answer-label">${t('Your answer','Câu trả lời')}<input id="answer-input" class="gap-input" data-answer="gap" value="${esc(ui.answer??'')}" maxlength="500" autocomplete="off" spellcheck="false" lang="en" ${attr} placeholder="${t('Type the missing word(s)…','Nhập từ còn thiếu…')}"></label>`;
 if(a.type==='order')return `<div class="order-workspace"><p class="fineprint">${t('Use the arrows to arrange the pieces. No dragging required.','Dùng mũi tên để xếp các mảnh. Không cần kéo thả.')}</p><ol class="order-list">${ui.answer.map((id,i)=>{const token=a.tokens.find(t=>t.id===id);return `<li><span class="order-number">${i+1}</span><span lang="en">${esc(token.text)}</span><div>${btn('↑','move',`data-id="${id}" data-dir="-1" ${i===0||disabled?'disabled':''} aria-label="${t('Move up','Đưa lên')}: ${esc(token.text)}"`)}${btn('↓','move',`data-id="${id}" data-dir="1" ${i===ui.answer.length-1||disabled?'disabled':''} aria-label="${t('Move down','Đưa xuống')}: ${esc(token.text)}"`)}</div></li>`;}).join('')}</ol></div>`;
 if(a.type==='match')return `<div class="match-grid">${a.pairs.map(p=>`<label class="match-row"><span lang="en">${esc(p.left)}</span><span aria-hidden="true">→</span><select data-match="${p.id}" ${attr} lang="en"><option value="">${t('Choose its connection','Chọn liên kết')}</option>${shuffle(a.pairs,a.id).map(q=>`<option value="${q.id}"${selected(ui.answer?.[p.id],q.id)}>${esc(q.right)}</option>`).join('')}</select></label>`).join('')}</div>`;
 return `<label class="answer-label">${t('Your field note','Ghi chép của bạn')}<textarea data-answer="writing" rows="5" maxlength="5000" lang="en" ${attr} placeholder="${t('Leave a little English in the world…','Để lại đôi dòng tiếng Anh…')}">${esc(ui.answer?.text??'')}</textarea></label><div class="rubric"><p><strong>${t('Self-review, not automatic scoring','Tự xem lại, không chấm điểm tự động')}</strong></p>${a.rubric.map((r,i)=>`<label><input type="checkbox" data-check="${i}" ${ui.answer?.checks.includes(i)?'checked':''} ${attr}>${esc(loc(r))}</label>`).join('')}</div>${!placement?btn(t('Compare with one possible example','So với một ví dụ tham khảo'),'model','','text-button'):''}${ui.showModel?`<blockquote lang="en">${esc(a.example)}</blockquote>`:''}`;
}
function feedbackView(a){
 const f=ui.feedback;if(!f)return '';
 return `<section class="feedback ${f.correct===false?'try-again':'success'}" role="status" tabindex="-1"><span class="feedback-symbol">${f.correct===false?'↻':'✦'}</span><div><h3>${f.correct===null?t('A field note worth keeping','Ghi chép đáng giữ lại'):f.correct?t('A connection made.','Bạn đã kết nối được.'):t('A clue for your next try.','Manh mối cho lần thử tiếp theo.')}</h3><p>${esc(loc(a.explanation))}</p>${f.correct===false?`<p class="solution"><strong>${t('One accepted answer:','Một câu trả lời được chấp nhận:')}</strong> <span lang="en">${esc(solution(a))}</span></p>`:''}${f.correct===null?`<p class="fineprint">${t('Your writing is saved as self-reviewed practice. This does not show independently assessed writing proficiency.','Bài viết được lưu là luyện tập tự xem lại, không phải bằng chứng năng lực viết đã được đánh giá độc lập.')}</p>`:ui.supported?`<p class="fineprint">${t('Supported practice: the discovery counts, but this is not independent evidence.','Luyện tập có hỗ trợ: khám phá được ghi nhận, nhưng không là bằng chứng độc lập.')}</p>`:''}<div class="button-row">${f.correct===false?btn(t('Revise my plan','Sửa câu trả lời'),'retry','','primary'):btn(t(ui.review?'Return to practice':'Keep exploring →',ui.review?'Trở lại ôn tập':'Tiếp tục khám phá →'),'next','','primary')}${f.correct===false?btn(t('Continue and revisit later','Tiếp tục và ôn lại sau'),'next'):''}</div></div></section>`;
}

function clueScene(m,a,r,done){return `<section class="kids-clue panel"><div class="clue-illustration">${islandArt(m.level,done)}</div><div><span class="nim-avatar" aria-hidden="true">✦</span><p class="eyebrow">${t('LOOK WHAT NIM FOUND','XEM NIM TÌM ĐƯỢC GÌ')}</p><h1>${t('A little clue. A new possibility.','Manh mối nhỏ. Khả năng mới.')}</h1><p>${esc(loc(a.instruction))}</p><section class="source-card"><p lang="en">${esc(a.context)}</p></section>${btn(t('I’m ready to try →','Mình sẵn sàng thử →'),'ready','','primary')} ${btn(t('Save & return to the map','Lưu và về bản đồ'),'atlas','','text-button')}</div></section>`;}
function discoveryScene(m,r,done){return `<section class="discovery-scene panel"><div class="discovery-art">${islandArt(m.level,done)}</div><p class="eyebrow">${t('THE WORLD OPENS A LITTLE MORE','THẾ GIỚI MỞ THÊM MỘT CHÚT')}</p><h1>${done===5?t('The field clues are connected.','Các manh mối đã kết nối.'):t('One more piece found its place.','Thêm một mảnh đã tìm được chỗ.')}</h1><p class="lede">${done===5?t('Return to your route to bring this discovery home.','Trở lại lộ trình để mang khám phá về.'):t(`${done} of 5 connections restored. Nim is keeping your discoveries safe.`,`${done} trong 5 kết nối đã được khôi phục. Nim giữ các khám phá giúp bạn.`)}</p><div class="discovery-pieces" aria-label="${done}/5">${m.activities.map(a=>`<span class="${progress.records[a.id]?.completed?'found':''}">${emblem(r.icon)}</span>`).join('')}</div>${btn(done===5?t('Return to the route →','Trở lại lộ trình →'):t('Follow the next clue →','Theo manh mối tiếp →'),'trail-next','','primary')}</section>`;}

function missionScreen(){
 const m=currentMission(),a=currentActivity(),mode=profile.settings.mode,r=REGIONS.find(r=>r.level===m.level),done=m.activities.filter(a=>progress.records[a.id]?.completed).length,number=m.activities.findIndex(x=>x.id===a.id)+1;
 const intro=mode==='kids'&&ui.stage==='intro';
 if(ui.stage==='world'||ui.stage==='board')return worldView();
 if(mode==='kids'&&ui.stage==='discovery')return discoveryScene(m,r,done);
 if(mode==='kids'&&ui.stage==='clue')return clueScene(m,a,r,done);
 return `<div class="expedition-header"><button type="button" class="back-link" data-action="atlas">← ${t('Back to the atlas','Về bản đồ')}</button><span class="chip">${m.level} · ${ui.review?t('Review','Ôn tập'):t('Expedition','Khám phá')}</span></div>
 <section class="mission-layout ${mode==='serious'?'study-layout':''}"><aside class="mission-aside"><p class="eyebrow">${esc(loc(r.name))}</p><h1>${esc(loc(m.title))}</h1>${mode!=='serious'?islandArt(m.level,done):''}<p>${esc(loc(m.objective))}</p><ol class="path-progress">${m.activities.map((x,i)=>`<li class="${progress.records[x.id]?.completed?'done':''} ${x.id===a.id?'current':''}">${btn(`<span>${progress.records[x.id]?.completed?'✓':i+1}</span><span>${{choice:t('Discover','Tìm hiểu'),gap:t('Restore','Khôi phục'),order:t('Build a plan','Lập kế hoạch'),match:t('Connect','Kết nối'),writing:t('Leave a note','Để lại ghi chép')}[x.type]}</span>`,'activity',`data-id="${x.id}" ${x.id===a.id?'aria-current="step"':''} ${mode==='kids'&&x.id!==a.id&&!progress.records[x.id]?.completed?'disabled':''}`)}</li>`).join('')}</ol><div class="reward-preview">${emblem(r.icon)}<small>${t('THIS DISCOVERY','KHÁM PHÁ NÀY')}</small><strong>${esc(loc(m.reward))}</strong></div>${mode==='serious'?`<p class="fineprint">${t('Evidence is recorded per activity. Hints and revealed solutions are tracked. No score is an official CEFR result.','Bằng chứng được ghi theo hoạt động. Gợi ý và đáp án đã xem được ghi nhận. Điểm số không phải kết quả CEFR chính thức.')}</p>`:''}</aside>
 <div class="activity-panel panel">${!intro?btn(t('← Explore this place','← Khám phá nơi này'),'world','','back-link'):''}${intro?`<div class="nim-intro"><span class="nim-avatar" aria-hidden="true">✦</span><p class="eyebrow">${t('NIM FOUND A NEW PLACE','NIM TÌM THẤY NƠI MỚI')}</p><h2>${t('Let’s see what’s waiting here.','Cùng xem điều gì đang chờ nhé.')}</h2><p class="lede">${esc(loc(m.summary))}</p><p>${t('Look for a clue, try an idea, and watch the map unfold. There is always another try.','Tìm manh mối, thử ý tưởng và xem bản đồ mở ra. Bạn luôn có thể thử lại.')}</p>${btn(t('Let’s investigate →','Cùng tìm hiểu →'),'investigate','','primary')}</div>`:`<div class="activity-top"><span class="eyebrow">${t('MOMENT','CHẶNG')} ${number} / 5</span><span class="activity-kind">${{choice:t('Choose a path','Chọn hướng'),gap:t('Restore the message','Khôi phục thông điệp'),order:t('Build the sequence','Xây thứ tự'),match:t('Find the connections','Tìm mối liên hệ'),writing:t('Make your mark','Để lại dấu ấn')}[a.type]}</span></div>${mode==='kids'?`<div class="nim-tip"><span aria-hidden="true">✦</span>${t('Nim says:','Nim nói:')} ${esc(loc(a.instruction))}</div>`:`<p class="instruction">${esc(loc(a.instruction))}</p>`}<section class="source-card"><div class="source-title"><span>${t('FIELD CLUE','MANH MỐI')}</span>${profile.settings.sound?btn(t('Read aloud','Đọc thành tiếng'),'speak','','text-button'):''}</div><p lang="en">${esc(a.context)}</p></section><h2 class="activity-prompt" lang="en">${esc(a.prompt)}</h2>${activityControls(a)}${!ui.feedback?`<div class="activity-actions">${btn(mode==='kids'?t('Try my idea ✦','Thử ý tưởng ✦'):t('Check my response','Kiểm tra câu trả lời'),'submit','','primary')}${a.type!=='writing'?btn(t('Show an answer','Xem đáp án'),'reveal','','text-button'):''}</div>${ui.showModel&&a.type!=='writing'?`<div class="hint-card"><strong>${t('Supported practice','Luyện tập có hỗ trợ')}</strong><p lang="en">${esc(solution(a))}</p></div>`:''}`:''}${feedbackView(a)}<p class="fineprint activity-save">${t('Responses save after checking. Drafts autosave after a short pause and when you leave.','Câu trả lời lưu sau khi kiểm tra. Bản nháp tự lưu sau khi bạn dừng gõ một chút và khi rời hoạt động.')} <span class="draft-status" role="status">${ui.feedback?t('Response saved','Đã lưu câu trả lời'):''}</span></p>`}</div></section>`;
}

function journalScreen(){
 const records=Object.values(progress.records),graded=records.filter(r=>content().activities.get(r.id).type!=='writing');
 const focuses=new Map();for(const r of graded){const f=focuses.get(r.focus)??{attempts:0,correct:0};f.attempts+=r.attempts;f.correct+=r.correct;focuses.set(r.focus,f);}
 return `<section class="page-heading"><p class="eyebrow">${t('YOUR FIELD JOURNAL','NHẬT KÝ KHÁM PHÁ')}</p><h1>${t('Look how far curiosity takes you.','Trí tò mò đưa bạn đi thật xa.')}</h1><p class="lede">${t('Discoveries tell your story. Evidence helps choose what to practice next.','Khám phá kể câu chuyện của bạn. Bằng chứng giúp chọn nội dung luyện tiếp.')}</p></section><div class="stats-grid">${[[progress.rewards.size,t('World discoveries','Khám phá thế giới')],[progress.independent,t('Items answered independently','Mục trả lời độc lập')],[progress.retained,t('Items recalled across 3+ days','Mục nhớ lại qua 3+ ngày')],[progress.due.length,t('Ready for review','Sẵn sàng ôn')]].map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="journal-grid"><section class="panel"><h2>${t('Language evidence','Bằng chứng ngôn ngữ')}</h2>${LEVELS.map(level=>{const rr=graded.filter(r=>r.level===level),n=rr.filter(r=>r.independent>0).length,total=pack.missions.filter(m=>m.level===level).flatMap(m=>m.activities).filter(a=>a.type!=='writing').length;return `<div class="level-evidence"><strong>${level}</strong><progress max="${total||1}" value="${n}" aria-label="${level} ${t('independent items','mục độc lập')}"></progress><span>${n}/${total}</span></div>`;}).join('')}<p class="fineprint">${t('These counts describe this library, not percentage mastery of a CEFR band. Reading and language-use items are automatically checked; writing is self-reviewed. Listening and speaking proficiency are not scored.','Số liệu mô tả thư viện này, không phải phần trăm thành thạo một mức CEFR. Đọc và sử dụng ngôn ngữ được kiểm tra tự động; viết do bạn tự xem lại. Không chấm năng lực nghe và nói.')}</p><p>${t('Practice suggestion','Gợi ý luyện tập')}: <strong>${progress.recommendation?.level??profile.journey.region}</strong> <span class="chip">${t('provisional','tạm thời')}</span></p>${btn(t('Revisit orientation','Làm lại định hướng'),'start-placement','','text-button')}</section><section class="panel"><h2>${t('Your discoveries','Các khám phá của bạn')}</h2>${progress.rewards.size?`<ul class="collection">${pack.missions.filter(m=>progress.rewards.has(m.id)).map(m=>`<li>${emblem(REGIONS.find(r=>r.level===m.level).icon)}<div><strong>${esc(loc(m.reward))}</strong><small>${m.level} · ${esc(loc(m.title))}</small></div>${btn('↗','begin',`data-id="${m.id}" aria-label="${esc(loc(m.title))}"`)}</li>`).join('')}</ul>`:`<div class="empty-state">${emblem('feather')}<p>${t('An empty page is an invitation. Your first discovery is waiting.','Trang trống là lời mời. Khám phá đầu tiên đang chờ bạn.')}</p>${btn(t('Explore the atlas','Khám phá bản đồ'),'atlas','','primary')}</div>`}</section></div><section class="panel"><h2>${t('Recent field notes','Ghi chép gần đây')}</h2>${records.filter(r=>r.last.result.correct===null).length?records.filter(r=>r.last.result.correct===null).slice(-8).reverse().map(r=>`<details><summary>${esc(loc(content().missions.get(r.missionId).title))} · ${new Date(r.last.at).toLocaleDateString(profile.settings.language)}</summary><p class="writing-entry" lang="en">${esc(r.last.answer.text)}</p><p class="fineprint">${t('Self-reviewed practice. Not automatically graded.','Luyện tập tự xem lại. Không chấm tự động.')}</p></details>`).join(''):`<p>${t('Notes you write on your journeys will appear here.','Ghi chép trên hành trình sẽ hiện ở đây.')}</p>`}</section>`;
}

function reviewScreen(){
 const due=progress.due,weak=Object.values(progress.records).filter(r=>r.last.result.correct===false&&!due.some(d=>d.id===r.id));
 const recommended=[...due,...weak];
 return `<section class="page-heading"><p class="eyebrow">${t('THE RETURN JOURNEY','HÀNH TRÌNH TRỞ LẠI')}</p><h1>${t('Some things are worth finding again.','Có những điều đáng tìm lại.')}</h1><p class="lede">${t('A little retrieval keeps a discovery close. Reviews are invitations; missed days never erase your progress.','Nhớ lại một chút giúp khám phá ở lại. Ôn tập là lời mời; bỏ một ngày không xóa tiến độ.')}</p></section><aside class="studio-invitation"><div><h2>${t('Visit the echo studio','Ghé phòng tiếng vang')}</h2><p>${t('Listen to a clue, retell it aloud, and compare with the transcript. Optional, ungraded practice.','Nghe manh mối, kể lại thành tiếng và so với lời thoại. Luyện tập tùy chọn, không chấm điểm.')}</p></div>${btn(t('Listen & speak ↗','Luyện nghe và nói ↗'),'studio','','primary')}</aside><section class="panel"><div class="section-heading"><h2>${recommended.length?t('Your practice satchel','Túi luyện tập'):t('You have room to explore.','Bạn có thể khám phá tiếp.')}</h2><span>${recommended.length} ${t('suggestions','gợi ý')}</span></div>${recommended.length?`<div class="review-list">${recommended.slice(0,20).map(r=>{const a=content().activities.get(r.id);return `<article><span class="chip">${r.level}</span><div><h3>${esc(loc(content().missions.get(r.missionId).title))}</h3><p lang="en">${esc(a.focus.replace(/-/g,' '))}</p><small>${r.last.result.correct===false?t('A recent difficulty — try retrieving before opening the answer.','Điểm cần luyện — thử nhớ lại trước khi xem đáp án.'):t('Scheduled recall','Nhớ lại theo lịch')}</small></div>${btn(t('Practice →','Ôn tập →'),'review-item',`data-id="${a.id}"`,'primary')}</article>`;}).join('')}</div>`:`<div class="empty-state">${emblem('leaf')}<p>${t('Nothing is due right now. Continue an expedition or revisit a favorite discovery.','Chưa có mục đến hạn. Tiếp tục chuyến khám phá hoặc trở lại khám phá yêu thích.')}</p>${btn(t('Open the atlas','Mở bản đồ'),'atlas','','primary')}</div>`}<p class="fineprint">${t('Scheduling uses a simple 1, 3, 7, 14, 30 day heuristic after independent recall on different days. Mistakes return sooner. It is a useful practice aid, not a validated memory model.','Lịch ôn dùng quy tắc đơn giản 1, 3, 7, 14, 30 ngày sau khi nhớ lại độc lập vào các ngày khác nhau. Mục sai trở lại sớm hơn. Đây là công cụ hỗ trợ, không phải mô hình trí nhớ đã được kiểm định.')}</p></section>`;
}

function studioScreen(){return studioView({missions:pack.missions,level:profile.journey.region,language:profile.settings.language,activityId:ui.studioId});}
function currentStudioActivity(){const activities=[...content().activities.values()].filter(a=>a.level===profile.journey.region&&a.skill==='reading');return activities.find(a=>a.id===ui.studioId)??activities[0];}
function speakText(text){if(!('speechSynthesis'in window))throw new Error(t('Read-aloud is unavailable. You can still read the transcript and rehearse aloud.','Không có giọng đọc. Bạn vẫn có thể đọc lời thoại và luyện nói.'));speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(text),profileId=profile.id;voice.lang='en-GB';voice.rate=profile.journey.region==='A1'?.85:1;voice.onerror=event=>{if(profile?.id===profileId&&!['canceled','interrupted'].includes(event.error))reportError(new Error(t('The browser voice could not play. Read the transcript and rehearse aloud, or try another device voice.','Giọng đọc không phát được. Hãy đọc lời thoại và luyện nói, hoặc thử giọng khác trên thiết bị.')));};speechSynthesis.speak(voice);}

function cloudPanel(){const s=ui.cloudStatus;return `<details class="cloud-panel" ${ui.showCloud?'open':''}><summary>${t('Optional family cloud','Đám mây gia đình tùy chọn')}</summary><p>${t('Use an approved family Google account to link selected profiles and synchronize this device. Assessed responses, including written work, are synchronized; unfinished drafts stay on this device. No cloud connection is needed to play locally.','Dùng tài khoản Google gia đình đã được duyệt để liên kết hồ sơ và đồng bộ thiết bị. Câu trả lời đã kiểm tra, gồm bài viết, được đồng bộ; bản nháp chưa nộp ở lại thiết bị. Không cần đám mây để chơi trên thiết bị.')}</p><p class="cloud-status" role="status">${esc(s.message||s.state)}</p>${!s.configured?`<p class="fineprint">${t('The owner has not configured a cloud project. Local saving, export and import work independently. Setup instructions are in the project deployment guide.','Chủ dự án chưa cấu hình đám mây. Lưu trên thiết bị, xuất và nhập bản sao vẫn hoạt động. Hướng dẫn cấu hình ở tài liệu triển khai.')}</p>`:s.uid?`<div class="button-row">${profile?btn(t('Link this profile to my account','Liên kết hồ sơ với tài khoản'),'cloud-link'):''}${profile?btn(t('Synchronize this profile','Đồng bộ hồ sơ'),'cloud-sync','','primary'):''}${btn(t('Restore my cloud profiles','Khôi phục hồ sơ đám mây'),'cloud-restore')}${btn(t('Sign out','Đăng xuất'),'cloud-signout')}</div>`:btn(t('Sign in with Google','Đăng nhập Google'),'cloud-signin','','primary')}</details>`;}

function settingsScreen(){return `<section class="page-heading"><p class="eyebrow">${t('MAKE YOURSELF AT HOME','THOẢI MÁI THEO CÁCH CỦA BẠN')}</p><h1>${t('A journey that fits you.','Hành trình phù hợp với bạn.')}</h1><p>${t('Preferences never change your learning evidence or erase discoveries.','Tùy chọn không thay đổi bằng chứng học tập hay xóa khám phá.')}</p></section><section class="panel"><h2>${t('Experience','Trải nghiệm')}</h2>${modeCards()}<div class="settings-grid"><label>${t('Guidance language','Ngôn ngữ hướng dẫn')}<select data-setting="language"><option value="en"${selected(profile.settings.language,'en')}>English only</option><option value="vi"${selected(profile.settings.language,'vi')}>Tiếng Việt hỗ trợ</option></select></label><label>${t('Visual quality','Chất lượng hình ảnh')}<select data-setting="quality">${['auto','eco','balanced','ultra'].map(q=>`<option value="${q}"${selected(profile.settings.quality,q)}>${{auto:t('Auto — adapt to this device','Tự động — theo thiết bị'),eco:t('Eco — quiet & lightweight','Tiết kiệm — nhẹ và tĩnh'),balanced:t('Balanced — a little atmosphere','Cân bằng — thêm không khí'),ultra:t('Ultra — richer atmosphere','Cao — phong phú hơn')}[q]}</option>`).join('')}</select></label><label>${t('Motion','Chuyển động')}<select data-setting="motion">${[['system',t('Follow device preference','Theo thiết bị')],['reduced',t('Reduce motion','Giảm chuyển động')],['full',t('Allow gentle motion','Cho phép chuyển động nhẹ')]].map(([v,l])=>`<option value="${v}"${selected(profile.settings.motion,v)}>${l}</option>`).join('')}</select></label><label>${t('Read-aloud assistance','Hỗ trợ đọc thành tiếng')}<select data-setting="sound"><option value="false"${selected(String(profile.settings.sound),'false')}>${t('Off','Tắt')}</option><option value="true"${selected(String(profile.settings.sound),'true')}>${t('Available on request','Đọc khi yêu cầu')}</option></select></label></div><p class="fineprint">${t('All quality levels have the same content. Auto starts with device signals and can lower decorative quality if frames are slow. Read-aloud uses your browser’s available voices, which may use its voice service; it is optional practice support, not a listening test.','Mọi chất lượng đều có cùng nội dung. Tự động dùng tín hiệu thiết bị và có thể giảm trang trí khi khung hình chậm. Đọc thành tiếng dùng giọng sẵn có của trình duyệt, có thể dùng dịch vụ giọng nói; đây là hỗ trợ tùy chọn, không phải bài đánh giá nghe.')}</p></section><section class="panel"><h2>${t('Your profile & backups','Hồ sơ và bản sao lưu')}</h2><p class="offline-status" role="status">${ui.offlineReady?t('Offline library ready on this device.','Thư viện ngoại tuyến đã sẵn sàng trên thiết bị.'):t('Offline library not yet confirmed. Keep a connection until the first full download finishes.','Chưa xác nhận thư viện ngoại tuyến. Giữ kết nối cho đến khi tải xong lần đầu.')}</p><form class="form-row" data-form="rename"><label>${t('Display name','Tên hiển thị')}<input name="name" value="${esc(profile.name)}" maxlength="40" required></label><button type="submit">${t('Save name','Lưu tên')}</button></form><p>${t('Local progress is private to this browser’s storage, but is accessible to other people using this browser. Export regularly before clearing site data.','Tiến độ nằm trong bộ nhớ trình duyệt và có thể được xem bởi người dùng chung trình duyệt. Hãy xuất bản sao trước khi xóa dữ liệu trang.')}</p><div class="button-row">${btn(t('Export all local profiles','Xuất mọi hồ sơ trên thiết bị'),'export','','primary')}${btn(t('Import / merge a backup','Nhập / gộp bản sao'),'import')}${btn(t('Request persistent device storage','Yêu cầu lưu trữ bền vững'),'persist')}</div><p class="fineprint">${t('Backups contain names and written practice. Keep them somewhere private. Imports merge immutable event IDs and reject conflicting history.','Bản sao chứa tên và bài viết luyện tập. Hãy giữ ở nơi riêng tư. Nhập bản sao gộp mã sự kiện và từ chối lịch sử mâu thuẫn.')}</p>${cloudPanel()}</section><section class="panel"><h2>${t('Family care','Đồng hành gia đình')}</h2><p>${t('A guardian can create dependent travelers, help choose their practice and view their journal on this device. Mode is a preference, not an age claim. These controls do not lock the shared browser.','Người giám hộ có thể tạo hồ sơ phụ thuộc, hỗ trợ chọn bài và xem nhật ký trên thiết bị này. Chế độ là sở thích, không xác định tuổi. Các chức năng không khóa trình duyệt dùng chung.')}</p>${profile.kind==='dependent'?`<p>${t('Guardian','Người giám hộ')}: <strong>${esc(profiles.find(p=>p.id===profile.guardianId)?.name??'—')}</strong></p>`:`<ul class="family-list">${profiles.filter(p=>p.guardianId===profile.id).map(p=>`<li><span>${esc(p.name)}</span>${btn(t('Open journal & preferences','Mở nhật ký và tùy chọn'),'dependent',`data-id="${p.id}"`)}</li>`).join('')}</ul>${btn(t('Add a family traveler','Thêm thành viên gia đình'),'profiles')}`}</section><section class="panel"><h2>${t('About this atlas','Về bản đồ này')}</h2><p>${t('Original all-ages learning expeditions across A1–C2. This is a finite foundation library, not a complete CEFR course. Automated checking covers bounded reading/language tasks. Writing is self-reviewed; speaking and listening are not assessed. No paid AI runs in the game.','Các chuyến khám phá nguyên bản cho mọi tuổi từ A1–C2. Đây là thư viện nền tảng hữu hạn, không phải khóa học CEFR hoàn chỉnh. Kiểm tra tự động giới hạn ở đọc và sử dụng ngôn ngữ. Viết do bạn tự xem lại; không đánh giá nói và nghe. Trò chơi không chạy AI trả phí.')}</p><details><summary>${t('Content references & rights','Nguồn tham khảo và quyền sử dụng')}</summary>${pack.provenance.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><br><small>${esc(s.usage)}</small></p>`).join('')}</details><details class="danger"><summary>${t('Remove this local profile','Xóa hồ sơ trên thiết bị')}</summary><p>${t('Export first if you want a recovery copy. This removes local history only. Cloud copies must be deleted separately. Guardians with dependent profiles cannot be removed until those dependents are removed.','Xuất bản sao trước nếu cần khôi phục. Việc này chỉ xóa lịch sử trên thiết bị. Bản đám mây phải xóa riêng. Không thể xóa người giám hộ còn hồ sơ phụ thuộc.')}</p><form data-form="delete"><label>${t('Type the display name to confirm','Nhập tên hiển thị để xác nhận')}<input name="confirm" autocomplete="off" required></label><button type="submit" class="danger-button">${t('Delete local profile','Xóa hồ sơ thiết bị')}</button></form>${btn(t('Delete this profile’s cloud copy','Xóa bản đám mây của hồ sơ'),'cloud-delete')}</details></section>`;}

function startPlacement(){
 globalThis.speechSynthesis?.cancel();
 ui.placement=[];ui.placementIndex=0;ui.placementItems=LEVELS.flatMap(l=>[...content().activities.values()].filter(a=>a.level===l&&['choice','gap'].includes(a.type)).slice(0,2));ui.screen='placement';ui.answer=null;ui.feedback=null;render(true);
}
function placementScreen(){
 const a=ui.placementItems[ui.placementIndex];
 if(!a){const rec=placementRecommendation(ui.placement);return `<section class="panel orientation"><p class="eyebrow">${t('A PLACE TO BEGIN','NƠI ĐỂ BẮT ĐẦU')}</p><h1>${t('Try the','Thử mức')} ${rec.level} ${t('practice range.','để luyện tập.')}</h1><p>${t('This short orientation sampled reading and language use from the learning library. It is not calibrated, does not test all skills, and cannot certify a CEFR level. Recognition, prior practice and a small sample affect the result.','Định hướng ngắn lấy mẫu đọc và sử dụng ngôn ngữ từ thư viện học. Bài chưa được hiệu chỉnh, không kiểm tra mọi kỹ năng và không chứng nhận CEFR. Việc đã gặp nội dung và cỡ mẫu nhỏ ảnh hưởng kết quả.')}</p><p>${t('You can change your practice range freely. Your later independent practice and review evidence are shown separately.','Bạn có thể đổi mức luyện tập tự do. Bằng chứng luyện tập độc lập và ôn tập tiếp theo được thể hiện riêng.')}</p>${btn(t('Begin from this range →','Bắt đầu ở mức này →'),'accept-placement',`data-value="${rec.level}"`,'primary')}</section>`;}
 return `<section class="panel orientation"><p class="eyebrow">${t('ORIENTATION','ĐỊNH HƯỚNG')} · ${ui.placementIndex+1}/${ui.placementItems.length}</p><h1>${t('Find a comfortable starting point.','Tìm nơi bắt đầu phù hợp.')}</h1><p class="fineprint">${t('Try without hints. If you do not know, skip. This does not affect world progress.','Thử không dùng gợi ý. Chưa biết thì bỏ qua. Bài này không ảnh hưởng tiến độ thế giới.')}</p><section class="source-card"><p lang="en">${esc(a.context)}</p></section><h2 class="activity-prompt" lang="en">${esc(a.prompt)}</h2>${activityControls(a,true)}<div class="button-row">${btn(t('Continue','Tiếp tục'),'placement-next','','primary')}${btn(t('I don’t know yet','Tôi chưa biết'),'placement-skip')}${btn(t('Leave orientation','Rời định hướng'),'atlas')}</div></section>`;
}

function render(focusHeading=false){
 const active=document.activeElement,focusKey=active?.dataset?.focusKey,selection=active&&'selectionStart'in active?[active.selectionStart,active.selectionEnd]:null;
 if(!profile&&ui.screen!=='profiles')ui.screen='profiles';
 const context=`${ui.screen}:${profile?.id??''}`;
 // Readiness/status notifications may rebuild this view while a person types.
 // Keep transient profile forms only within the same view and learner. Explicit
 // navigation and successful create/delete flows render with focusHeading=true.
 const forms=!focusHeading&&context===renderedContext?[...app.querySelectorAll('form[data-form]')].map(form=>({
  name:form.dataset.form,open:form.closest('details')?.open,
  controls:[...form.elements].filter(el=>el.name&&el.type!=='file').map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked})),
 })):[];
 const screens={profiles:profilesScreen,onboard:onboardScreen,atlas:atlasScreen,mission:missionScreen,journal:journalScreen,review:reviewScreen,settings:settingsScreen,placement:placementScreen,studio:studioScreen};
 document.body.className=`mode-${profile?.settings.mode??'balanced'}`;
 app.innerHTML=`${header()}<main id="main" tabindex="-1">${ui.error?`<div class="alert error" role="alert">${esc(ui.error)} ${btn(t('Dismiss','Đóng'),'dismiss-error','','text-button')}</div>`:''}${ui.notice?`<div class="alert notice" role="status">${esc(ui.notice)} ${btn(t('Dismiss','Đóng'),'dismiss-notice','','text-button')}</div>`:''}${screens[ui.screen]()}</main>${footer()}`;
 for(const saved of forms){
  const form=[...app.querySelectorAll('form[data-form]')].find(el=>el.dataset.form===saved.name);if(!form)continue;
  const controls=[...form.elements].filter(el=>el.name&&el.type!=='file');
  saved.controls.forEach((value,index)=>{const el=controls[index];if(!el||el.name!==value.name||el.type!==value.type)return;
   if(el.tagName==='SELECT'&&![...el.options].some(option=>option.value===value.value))return;
   el.value=value.value;if(el.type==='checkbox'||el.type==='radio')el.checked=value.checked;
  });
  const details=form.closest('details');if(details&&saved.open!==undefined)details.open=saved.open;
 }
 app.querySelectorAll('button,input,select,textarea,summary,a').forEach((el,i)=>{
  const form=el.closest('form[data-form]')||(el.tagName==='SUMMARY'?el.parentElement.querySelector('form[data-form]'):null);
  el.dataset.focusKey=form?`form-${form.dataset.form}-${el.name||el.tagName}`:`${el.dataset.action??el.dataset.setting??el.dataset.answer??el.dataset.match??el.tagName}-${el.dataset.id??el.dataset.value??el.name??i}-${el.dataset.dir??''}`;
 });
 renderedContext=context;
 if(focusHeading){const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}scrollTo({top:0,behavior:'instant'});}
 else if(focusKey){const target=[...app.querySelectorAll('[data-focus-key]')].find(e=>e.dataset.focusKey===focusKey);if(target){target.focus({preventScroll:true});if(selection&&'setSelectionRange'in target&&target.type!=='checkbox')try{target.setSelectionRange(...selection);}catch{}}}
 app.setAttribute('aria-busy',String(ui.busy));
}

async function submit(){
 const a=currentActivity(),answer=structuredClone(ui.answer),result=assess(a,answer);if(!result.complete)throw new Error(t(a.type==='writing'?'Write at least a short response and check each self-review point.':'Complete your response first.','Hãy hoàn thành câu trả lời và các mục tự xem lại nếu có.'));
 ui.submitting=true;app.querySelectorAll('.activity-panel button,.activity-panel input,.activity-panel select,.activity-panel textarea').forEach(el=>el.disabled=true);
 try{await append('attempt',{activityId:a.id,missionId:ui.mission,contentVersion:pack.batchId,answer,supported:ui.supported,mode:profile.settings.mode});ui.answer=answer;ui.feedback=result;ui.draftKey=JSON.stringify({answer,supported:ui.supported});}
 finally{ui.submitting=false;}
 render();app.querySelector('.feedback')?.focus({preventScroll:true});
}
async function advance(){
 if(ui.review){await navigate('review');return;}
 if(profile.settings.mode==='kids'){
  if(ui.feedback?.correct===false){await navigate('atlas');return;}
  ui.stage='discovery';render(true);return;
 }
 if(profile.settings.mode==='balanced'){ui.stage='world';ui.feedback=null;render(true);return;}
 await continueTrail();
}
async function continueTrail(){
 const m=currentMission(),i=m.activities.findIndex(a=>a.id===ui.activity);
 if(i<m.activities.length-1){initActivity(m.activities[i+1]);ui.stage=profile.settings.mode==='kids'?'clue':'activity';render(true);}
 else if(progress.completedMissions.has(m.id)&&!progress.rewards.has(m.id)){ui.stage='world';ui.feedback=null;render(true);}
 else {ui.notice=progress.rewards.has(m.id)?`${t('Discovery restored:','Đã khôi phục khám phá:')} ${loc(m.reward)}`:t('Your progress is saved. Revisit unfinished moments to complete this discovery.','Tiến độ đã lưu. Trở lại các chặng chưa xong để hoàn thành khám phá.');await navigate('atlas');}
}

async function action(name,el){
 if(name==='dismiss-error'){ui.error='';render();return;}if(name==='dismiss-notice'){ui.notice='';render();return;}
 if(name==='profiles'){await navigate('profiles');return;}
 if(['atlas','journal','review','settings'].includes(name)){await navigate(name);if(name==='settings')cloud.prepare?.().catch(reportError);return;}
 if(name==='choose-profile'){await saveDraft();await selectProfile(el.dataset.id);render(true);return;}
 if(name==='dependent'){await selectProfile(el.dataset.id);ui.screen='journal';render(true);return;}
 if(name==='mode'){await saveDraft();profile=await store.updateProfile(profile.id,{settings:{mode:el.dataset.value}});setPreferences();render();return;}
 if(name==='region'){await saveDraft();profile=await store.updateProfile(profile.id,{journey:{region:el.dataset.value}});render(true);return;}
 if(name==='finish-onboard'){profile=await store.updateProfile(profile.id,{journey:{onboarded:true}});await navigate('atlas');return;}
 if(name==='begin'){await beginMission(el.dataset.id);return;}
 if(name==='review-item'){const a=content().activities.get(el.dataset.id);await beginMission(a.missionId,a);return;}
 if(name==='activity'){await saveDraft();initActivity(content().activities.get(el.dataset.id));ui.stage=profile.settings.mode==='kids'&&!ui.review?'clue':'activity';render(true);return;}
 if(name==='investigate'){ui.stage='world';render(true);return;}
 if(name==='ready'){ui.stage='activity';render(true);return;}
 if(name==='board'||name==='world'){await saveDraft();globalThis.speechSynthesis?.cancel();ui.stage='world';ui.feedback=null;render(true);return;}
 if(name==='trail-next'){await continueTrail();return;}
 if(name==='studio'){await navigate('studio');return;}
 if(name==='studio-listen'){speakText(currentStudioActivity().context);return;}
 if(name==='studio-stop'){globalThis.speechSynthesis?.cancel();return;}
 if(name==='world-inspect'){ui.worldInspected=[Number(el.dataset.x),Number(el.dataset.y)];render();return;}
 if(name==='world-move'){const command=el.dataset.value;if(profile.settings.mode==='kids')await runWorld([command]);else if(profile.settings.mode==='serious'){const plan=parseWorldPlan(ui.worldPlan??'');if(plan.length>=40)throw new Error(t('Run or clear this route before adding more.','Thử hoặc xóa lộ trình trước khi thêm.'));ui.worldPlan=[...plan,command].join(' ');render();}else{ui.worldQueue??=[];if(ui.worldQueue.length>=40)throw new Error(t('Try your plan before adding more steps.','Thử kế hoạch trước khi thêm bước.'));ui.worldQueue.push(command);render();}return;}
 if(name==='world-run'){const commands=profile.settings.mode==='serious'?parseWorldPlan(ui.worldPlan??''):ui.worldQueue??[];if(!commands.length)throw new Error(t('Add a few route commands first.','Thêm lệnh đi trước nhé.'));await runWorld(commands);ui.worldQueue=[];ui.worldPlan='';render();return;}
 if(name==='world-clear'){ui.worldQueue=[];ui.worldPlan='';render();return;}
 if(name==='world-reset'){await saveWorld([]);ui.worldQueue=[];ui.worldPlan='';ui.worldRoute=null;render();return;}
 if(name==='world-translate'){ui.worldTranslation=!ui.worldTranslation;await saveWorld(progress.worlds.states[currentBoard().id]?.commands??[]);return;}
 if(name==='world-hint'){ui.worldHint=true;await saveWorld(progress.worlds.states[currentBoard().id]?.commands??[]);return;}
 if(name==='world-route'){ui.worldHint=true;ui.worldRoute=findRoute(currentBoard());await saveWorld(progress.worlds.states[currentBoard().id]?.commands??[]);return;}
 if(name==='choose'){ui.answer=el.dataset.value;queueDraft();render();return;}
 if(name==='move'){const i=ui.answer.indexOf(el.dataset.id),j=i+Number(el.dataset.dir);if(j>=0&&j<ui.answer.length)[ui.answer[i],ui.answer[j]]=[ui.answer[j],ui.answer[i]];queueDraft();render();return;}
 if(name==='submit'){await submit();return;}
 if(name==='retry'){ui.feedback=null;ui.supported=true;ui.showModel=false;render();return;}
 if(name==='reveal'||name==='model'){const activity=currentActivity();await append('support',{activityId:activity.id,reason:'answer-revealed'});ui.showModel=true;ui.supported=true;queueDraft();render();return;}
 if(name==='next'){await advance();return;}
 if(name==='start-placement'){await saveDraft();startPlacement();return;}
 if(name==='placement-next'||name==='placement-skip'){
  const a=ui.placementItems[ui.placementIndex],r=assess(a,ui.answer);if(name==='placement-next'&&!r.complete)throw new Error(t('Choose a response or skip this item.','Chọn câu trả lời hoặc bỏ qua mục này.'));ui.placement.push({level:a.level,correct:name==='placement-next'&&r.correct===true});ui.placementIndex++;ui.answer=null;render(true);return;
 }
 if(name==='accept-placement'){const recommendation=placementRecommendation(ui.placement);await append('placement',recommendation);profile=await store.updateProfile(profile.id,{journey:{region:recommendation.level,onboarded:true}});await navigate('atlas');return;}
 if(name==='speak'){speakText(currentActivity().context);return;}
 if(name==='export'){await saveDraft();const data=await store.exportAll(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`unfolding-atlas-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ui.notice=t('Backup exported. Keep it somewhere private.','Đã xuất bản sao. Hãy giữ ở nơi riêng tư.');render();return;}
 if(name==='import'){document.querySelector('#import-file').click();return;}
 if(name==='persist'){const granted=await navigator.storage?.persist?.();ui.notice=granted?t('This browser granted persistent storage. Backups are still useful.','Trình duyệt đã cấp lưu trữ bền vững. Bản sao lưu vẫn hữu ích.'):t('Persistent storage was not granted. Local saving still works; keep a backup.','Chưa được cấp lưu trữ bền vững. Lưu trên thiết bị vẫn hoạt động; hãy giữ bản sao.');render();return;}
 if(name==='cloud-panel'){ui.showCloud=true;await cloud.prepare();render();return;}
 const operations={'cloud-signin':()=>cloud.signIn(),'cloud-signout':()=>cloud.signOut(),'cloud-link':()=>cloud.linkProfile(profile.id),'cloud-sync':()=>cloud.sync(profile.id),'cloud-restore':()=>cloud.restoreProfiles(),'cloud-delete':()=>{if(!confirm(t('Delete this profile’s cloud copy? Local progress stays on this device.','Xóa bản đám mây? Tiến độ trên thiết bị được giữ lại.')))return;return cloud.deleteRemoteProfile(profile.id);}};
 if(operations[name]){await saveDraft();await operations[name]();await refresh();render();}
}
// Background work may fail while a foreground action still owns the interaction
// lock. Only run() releases that lock, after its awaited operation finishes.
function reportError(error){ui.error=errorMessage(error);render();}
async function run(task){if(ui.busy)return;ui.busy=true;app.setAttribute('aria-busy','true');try{await task();}catch(error){reportError(error);}finally{ui.busy=false;app.setAttribute('aria-busy','false');}}
app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(el.disabled)return;run(()=>action(el.dataset.action,el));});
app.addEventListener('input',e=>{
 const el=e.target;if(ui.submitting)return;if(el.dataset.answer==='gap')ui.answer=el.value;
 if(el.dataset.answer==='writing')ui.answer={...ui.answer,text:el.value};
 if(el.hasAttribute('data-world-plan'))ui.worldPlan=el.value;
 if(el.dataset.answer)queueDraft();
});
app.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.answer==='gap'&&!ui.feedback){e.preventDefault();run(()=>ui.screen==='placement'?action('placement-next',e.target):submit());}});
app.addEventListener('keydown',e=>{const direction={ArrowUp:'N',ArrowRight:'E',ArrowDown:'S',ArrowLeft:'W'}[e.key];if(direction&&e.target.closest('.expedition-grid')){e.preventDefault();run(async()=>{await action('world-move',{dataset:{value:direction}});app.querySelector('.world-cell.nim-here')?.focus({preventScroll:true});});}});
app.addEventListener('toggle',e=>{if(e.target.classList?.contains('cloud-panel')&&app.contains(e.target)){const opening=e.target.open&&!ui.showCloud;ui.showCloud=e.target.open;if(opening)cloud?.prepare().catch(reportError);}},true);
const handleChange=e=>run(async()=>{
 const el=e.target;
 if(el.hasAttribute('data-studio-item')){ui.studioId=el.value;globalThis.speechSynthesis?.cancel();render();}
 if(el.dataset.setting){await saveDraft();profile=await store.updateProfile(profile.id,{settings:{[el.dataset.setting]:el.dataset.setting==='sound'?el.value==='true':el.value}});setPreferences();render();}
 if(el.dataset.journey){profile=await store.updateProfile(profile.id,{journey:{[el.dataset.journey]:el.value}});render();}
 if(el.dataset.match){ui.answer={...ui.answer,[el.dataset.match]:el.value};queueDraft();}
 if(el.dataset.check!==undefined){const set=new Set(ui.answer.checks);el.checked?set.add(Number(el.dataset.check)):set.delete(Number(el.dataset.check));ui.answer={...ui.answer,checks:[...set]};queueDraft();}
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];el.value='';if(file.size>STORE_LIMITS.importBytes)throw new Error(t('Backup is too large.','Bản sao quá lớn.'));const data=JSON.parse(await file.text());await store.importAll(data);await refresh();ui.notice=t('Backup validated and merged. Existing history was preserved.','Bản sao đã kiểm tra và gộp. Lịch sử hiện có được giữ lại.');render();}
});
app.addEventListener('change',handleChange);
importInput.addEventListener('change',handleChange);
app.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);run(async()=>{
 if(form.dataset.form==='create-profile'){const kind=data.get('kind');const p=await store.createProfile({name:data.get('name'),kind,guardianId:kind==='dependent'?data.get('guardianId'):null});await selectProfile(p.id);render(true);}
 if(form.dataset.form==='rename'){profile=await store.updateProfile(profile.id,{name:data.get('name')});await refresh();ui.notice=t('Name saved.','Đã lưu tên.');render();}
 if(form.dataset.form==='delete'){if(data.get('confirm')!==profile.name)throw new Error(t('The name does not match.','Tên chưa khớp.'));await store.deleteProfile(profile.id);profile=null;setActive('');setPreferences();await refresh();ui.screen='profiles';render(true);}
});});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&profile)saveDraft().catch(reportError);if(!document.hidden&&profile)refresh().then(()=>{if(ui.screen!=='mission'&&ui.screen!=='placement')render();}).catch(reportError);});
window.addEventListener('atlas:store-change',()=>{if(!ui.busy&&profile)refresh().then(()=>{if(!['mission','placement'].includes(ui.screen))render();}).catch(reportError);});
window.addEventListener('offline',()=>{ui.notice=ui.offlineReady?t('You’re offline. Downloaded journeys and local saving are available. Synchronize when you reconnect.','Bạn đang ngoại tuyến. Hành trình đã tải và lưu trên thiết bị vẫn dùng được. Hãy đồng bộ khi kết nối lại.'):t('You’re offline. Keep this tab open to continue. Local saving works; reopening may need a connection until the offline library is ready.','Bạn đang ngoại tuyến. Giữ thẻ này để tiếp tục. Vẫn lưu trên thiết bị; mở lại có thể cần kết nối nếu thư viện ngoại tuyến chưa sẵn sàng.');render();});
window.addEventListener('online',()=>{ui.notice=t('Connection restored. You can synchronize your linked profile in Settings.','Đã kết nối lại. Bạn có thể đồng bộ hồ sơ đã liên kết trong Cài đặt.');render();});

async function boot(){
 try{
  const [response,worldResponse]=await Promise.all([fetch(new URL('../data/published/atlas.json',import.meta.url)),fetch(new URL('../data/published/boards.json',import.meta.url))]);if(!response.ok||!worldResponse.ok)throw new Error('The atlas library could not load. Please reload when connected.');pack=await response.json();const worlds=await worldResponse.json();boards=worlds.boards;if(pack.schemaVersion!==1||!pack.missions?.length||!Array.isArray(boards)||pack.missions.some(m=>!boards.some(b=>b.missionId===m.id)))throw new Error('The atlas library is incomplete.');
  store=await openStore();profiles=await store.listProfiles();cloud=createCloud({store,onStatus:s=>{ui.cloudStatus=s;if(pack&&store&&!ui.busy&&!['mission','placement'].includes(ui.screen))render();}});ui.cloudStatus=cloud.status();
  let active;try{active=localStorage.getItem('atlas-active-profile');}catch{}
  if(active&&profiles.some(p=>p.id===active))await selectProfile(active);else ui.screen='profiles';
  render(true);registerOffline({onReady:()=>{ui.offlineReady=true;if(!['mission','placement'].includes(ui.screen))render();},onUpdate:()=>{ui.notice=t('An atlas update is ready. It will activate after all atlas tabs close; your progress stays saved.','Có bản cập nhật. Bản mới dùng sau khi đóng mọi thẻ bản đồ; tiến độ được giữ.');render();}}).catch(()=>{});
 }catch(error){app.innerHTML=`<main class="startup-error panel"><img src="./assets/atlas-mark.svg" alt="" width="50"><h1>The atlas needs a moment.</h1><p>${esc(errorMessage(error))}</p><p>Existing progress has not been reset. Check your connection and allow browser storage for this site.</p><button type="button" id="reload">Try again</button></main>`;document.querySelector('#reload').onclick=()=>location.reload();}
}
boot();
